
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b5050lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b5050lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.220771632484191e+00, -2.179469062719849e+00, -2.121615194642387e+00, -2.041516453358389e+00, -1.932459935782332e+00, -1.787489975647665e+00, -1.601231917740809e+00, -1.373104847100547e+00, -1.111326331548874e+00, -8.339545438130439e-01, -5.622361032354810e-01, -3.889709665162891e-01, -3.382837606944773e-01, -2.820853479328366e-01, -2.042999740839378e-01, -1.255513822637739e-01, -7.063433138623414e-02, -4.470331566027544e-02, -2.659884239991417e-02, -1.763863189749551e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


